import React, { useState } from 'react';
import './app.css';
import CommandInput from './components/CommandInput';
import CommandOutput from './components/CommandOutput';
import FileUploader from './components/FileUploader';
import ReportsViewer from './components/ReportsViewer';
import './components/ReportsViewer.css'; // Importar los estilos

function App() {
  const [commands, setCommands] = useState('');
  const [output, setOutput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [activeTab, setActiveTab] = useState('commands'); // 'commands' o 'reports'

  const handleFileLoad = (fileContent) => {
    setCommands(fileContent);
  };

  const executeCommands = async () => {
    if (!commands.trim()) {
      setOutput('No hay comandos para ejecutar.');
      return;
    }

    // Contar comandos válidos
    const validCommands = commands
      .split('\n')
      .map((line, index) => ({ line: line.trim(), number: index + 1 }))
      .filter(cmd => cmd.line !== '' && !cmd.line.startsWith('#'));

    setIsLoading(true);

    if (validCommands.length === 1) {
      setOutput(`Ejecutando comando en línea ${validCommands[0].number}...\n`);
    } else {
      setOutput(`Ejecutando ${validCommands.length} comandos en secuencia (continúa con errores)...\n`);
    }

    try {
      const response = await fetch('http://localhost:8080/execute', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          commands: commands
        }),
      });

      if (!response.ok) {
        throw new Error(`Error del servidor: ${response.status}`);
      }

      const result = await response.json();

      if (result.output) {
        setOutput(result.output);
      } else if (result.error) {
        setOutput(`Error: ${result.error}`);
      } else {
        setOutput('Respuesta del servidor sin contenido válido.');
      }

    } catch (error) {
      setOutput(`Error de conexión: ${error.message}\n\nVerifica que el servidor esté ejecutándose en http://localhost:8080`);
    } finally {
      setIsLoading(false);
    }
  };

  const clearCommands = () => {
    setCommands('');
  };

  const clearOutput = () => {
    setOutput('');
  };

  return (
    <div className="App">
      <header className="App-header">
        <h1>MIA - Sistema de Archivos</h1>
        <p>Proyecto 1 - Manejo e Implementación de Archivos</p>

        {/* Menú de navegación entre pestañas */}
        <nav className="app-nav">
          <button 
            className={`nav-tab ${activeTab === 'commands' ? 'active' : ''}`}
            onClick={() => setActiveTab('commands')}
          >
            Comandos
          </button>
          <button 
            className={`nav-tab ${activeTab === 'reports' ? 'active' : ''}`}
            onClick={() => setActiveTab('reports')}
          >
            Reportes
          </button>
        </nav>
      </header>

      <main className="App-main">
        {activeTab === 'commands' ? (
          <div className="container">
            <div className="input-section">
              <div className="section-header">
                <h2>Área de Entrada de Comandos</h2>
                <div className="button-group">
                  <FileUploader onFileLoad={handleFileLoad} />
                  <button onClick={clearCommands} className="btn-secondary">
                    Limpiar
                  </button>
                </div>
              </div>

              <CommandInput 
                value={commands}
                onChange={setCommands}
                placeholder="Ingresa los comandos aquí, uno por línea:

Ejemplo:
mkdisk -size=3000 -unit=k -path=disk1.mia
mkdisk -size=5000 -unit=m -path=disk2.mia
fdisk -size=1000 -path=disk1.mia -name=part1

# Los comentarios empiezan con #
# Cada línea es un comando separado"
              />

              <div className="execute-section">
                <button 
                  onClick={executeCommands}
                  disabled={isLoading || !commands.trim()}
                  className="btn-execute"
                >
                  {isLoading ? 'Ejecutando...' : 'Ejecutar Comandos'}
                </button>
              </div>
            </div>

            <div className="output-section">
              <div className="section-header">
                <h2>Área de Salida de Comandos</h2>
                <button onClick={clearOutput} className="btn-secondary">
                  Limpiar Salida
                </button>
              </div>

              <CommandOutput 
                output={output}
                isLoading={isLoading}
              />
            </div>
          </div>
        ) : (
          <ReportsViewer />
        )}
      </main>
    </div>
  );
}

export default App;
